using System;
using System.Collections.Generic;
using System.Globalization;
using System.Linq;
using System.Reflection;
using MelloCharts;

public static class ProfessionalChartTests {
    static int passed,failed;
    static void Test(string name,Action body){try{body();passed++;Console.WriteLine("PASS "+name);}catch(Exception e){failed++;Console.WriteLine("FAIL "+name+": "+e.Message);}}
    static void Is(bool b,string message){if(!b)throw new Exception(message);}
    static void Near(double got,double expected,double tolerance){Is(Math.Abs(got-expected)<=tolerance,"Expected "+expected+", got "+got);}
    static void Reject(Action a){try{a();}catch(ArgumentException){return;}throw new Exception("Invalid input accepted");}
    static void Set(ChartRow r,string name,object value){FieldInfo f=typeof(ChartRow).GetField(name);Is(f!=null,"Missing data field "+name);f.SetValue(r,value);}
    static T Get<T>(ChartRow r,string name){return (T)typeof(ChartRow).GetField(name).GetValue(r);}
    static void Finite(Scene s){foreach(SceneElement e in s.Elements){foreach(double v in new[]{e.X,e.Y,e.W,e.H,e.X2,e.Y2,e.Size})Is(!Double.IsNaN(v)&&!Double.IsInfinity(v),"Nonfinite "+e.Role);Is(e.W>=0&&e.H>=0,"Negative dimensions "+e.Role);if(e.Type!="line")Is(e.X>=0&&e.Y>=0&&e.X+e.W<=1280.01&&e.Y+e.H<=720.01,"Outside canvas "+e.Role);}}
    public static int Main(){
        Test("professional examples survive JSON and CSV with dedicated headers",delegate{foreach(string type in new[]{"gantt","scatter","bubble"}){ChartDocument d=ChartCore.Example(type);Is(d.source.Contains("fict"),"Example lacks fictitious provenance");string csv=ChartCore.ToCsv(d);Is(csv.StartsWith("\uFEFFcategoria;"+(type=="gantt"?"inicio;fim;progresso":"x;y")),"Wrong columns");ChartDocument fromCsv=ChartCore.ImportDelimited(csv,type),copy=ChartCore.Clone(d);Is(fromCsv.rows.Count==d.rows.Count&&copy.rows.Count==d.rows.Count,"Rows lost");Finite(ChartCore.BuildScene(copy));}});
        Test("scatter imports signed coordinates without financial fields",delegate{ChartDocument d=ChartCore.ImportDelimited("categoria;x;y\nA;-12,5;3,25\nB;8;-9","scatter");Near(Get<double>(d.rows[0],"x"),-12.5,0);Near(Get<double>(d.rows[1],"y"),-9,0);ChartDocument copy=ChartCore.Clone(d);Near(Get<double>(copy.rows[0],"x"),-12.5,0);Is(ChartCore.BuildScene(d).Elements.Count(e=>e.Role=="point")==2,"Scatter points missing");});
        Test("minimal professional JSON requires only its relevant values",delegate{string json="{\"version\":1,\"type\":\"scatter\",\"title\":\"Teste\",\"subtitle\":\"\",\"source\":\"\",\"unit\":\"\",\"palette\":\"ocean\",\"decimals\":0,\"showLabels\":true,\"showBaseline\":false,\"includeTotal\":false,\"rows\":[{\"label\":\"A\",\"x\":-3,\"y\":7}]}";ChartDocument d=ChartCore.Deserialize(json);Near(Get<double>(d.rows[0],"x"),-3,0);Reject(delegate{ChartCore.Deserialize(json.Replace("\"x\":-3","\"x\":null"));});});
        Test("Gantt normalizes Brazilian and Excel serial dates to ISO",delegate{ChartDocument d=ChartCore.ImportDelimited("categoria;inicio;fim;progresso\nA;28/10/2026;30/10/2026;25\nB;46323;46324;0","gantt");Is(Get<string>(d.rows[0],"startDate")=="2026-10-28","Brazilian date not normalized");Is(Get<string>(d.rows[1],"startDate")=="2026-10-28","Excel date not normalized");Is(ChartCore.ToCsv(d).Contains("2026-10-28;2026-10-30;25"),"CSV dates not ISO");});
        Test("Gantt rejects impossible reversed missing or ambiguous dates",delegate{foreach(string dates in new[]{"2026-02-30;2026-03-01","2026-10-30;2026-10-28",";2026-10-28","10/28/2026;2026-10-29","60;61"})Reject(delegate{ChartCore.ImportDelimited("categoria;inicio;fim;progresso\nA;"+dates+";50","gantt");});});
        Test("Gantt rejects progress outside percent range",delegate{foreach(string p in new[]{"-1","101","NaN","Infinity"})Reject(delegate{ChartCore.ImportDelimited("categoria;inicio;fim;progresso\nA;2026-10-28;2026-10-30;"+p,"gantt");});});
        Test("bubble rejects zero negative nonfinite and absent sizes",delegate{foreach(string size in new[]{"0","-1","NaN","Infinity",""})Reject(delegate{ChartCore.ImportDelimited("categoria;x;y;tamanho\nA;-3;4;"+size,"bubble");});});
        Test("bubble area is proportional to size and preserves signed positions",delegate{ChartDocument d=ChartCore.ImportDelimited("categoria;x;y;tamanho\nA;-10;-20;4\nB;10;20;16","bubble");List<SceneElement> b=ChartCore.BuildScene(d).Elements.Where(e=>e.Role=="bubble").OrderBy(e=>e.Category).ToList();Is(b.Count==2,"Bubbles missing");Near(b[1].W*b[1].H/(b[0].W*b[0].H),4,.000001);Is(b[0].X<b[1].X&&b[0].Y>b[1].Y,"Coordinate direction reversed");});
        Test("Gantt progress segments reflect completion and same day tasks remain visible",delegate{ChartDocument d=ChartCore.ImportDelimited("categoria;inicio;fim;progresso\nA;2026-10-28;2026-10-30;25\nMarco;2026-10-31;2026-10-31;100","gantt");Scene s=ChartCore.BuildScene(d);SceneElement a=s.Elements.First(e=>e.Role=="ganttBar"&&e.Category==0),p=s.Elements.First(e=>e.Role=="ganttProgress"&&e.Category==0);Near(p.W/a.W,.25,.000001);Is(s.Elements.Any(e=>e.Category==1&&e.Role=="ganttBar"&&e.W>0),"Same day task invisible");Finite(s);});
        Test("professional imports reject duplicate headers and uneven rows",delegate{Reject(delegate{ChartCore.ImportDelimited("categoria;x;x;y\nA;1;2;3","scatter");});Reject(delegate{ChartCore.ImportDelimited("categoria;x;y\nA;1","scatter");});});
        Test("professional row limits accept full data and reject one extra",delegate{foreach(string type in new[]{"gantt","scatter","bubble"}){ChartDocument d=ChartCore.Example(type);ChartRow row=d.rows[0];int limit=type=="gantt"?24:80;d.rows=Enumerable.Range(0,limit).Select(i=>ChartCore.Clone(new ChartDocument{version=1,type=type,title=d.title,subtitle=d.subtitle,source=d.source,unit=d.unit,palette=d.palette,style=d.style,decimals=d.decimals,showLabels=true,showGrid=true,rows=new List<ChartRow>{row}}).rows[0]).ToList();ChartCore.Validate(d);Finite(ChartCore.BuildScene(d));Is(ChartCore.ImportDelimited(ChartCore.ToCsv(d),type).rows.Count==limit,"Full table not imported");d.rows.Add(row);Reject(delegate{ChartCore.Validate(d);});}});
        Test("professional themes and extreme coordinates stay finite inside canvas",delegate{foreach(string type in new[]{"gantt","scatter","bubble"})foreach(string style in new[]{"executive","minimal","dark"}){ChartDocument d=ChartCore.Example(type);d.style=style;d.title=new string('W',80);if(type!="gantt"){for(int i=0;i<d.rows.Count;i++){Set(d.rows[i],"x",i%2==0?-1000000000.0:1000000000.0);Set(d.rows[i],"y",i%2==0?1000000000.0:-1000000000.0);}}Scene s=ChartCore.BuildScene(d);Finite(s);Is(s.Elements.First(e=>e.Role=="background").Color==(style=="dark"?"#101E2E":"#FFFFFF"),"Theme background wrong");}});
        Test("all zero and subnormal scatter coordinates render finite geometry",delegate{ChartDocument d=ChartCore.ImportDelimited("categoria;x;y\nA;0;0","scatter");Finite(ChartCore.BuildScene(d));Set(d.rows[0],"x",Double.Epsilon);Set(d.rows[0],"y",-Double.Epsilon);Finite(ChartCore.BuildScene(d));});
        Test("hidden labels and grid retain every editable mark",delegate{foreach(string type in new[]{"gantt","scatter","bubble"}){ChartDocument d=ChartCore.Example(type);d.showGrid=false;d.showLabels=false;Scene s=ChartCore.BuildScene(d);Is(!s.Elements.Any(e=>e.Role=="grid"||e.Role=="value"||e.Role=="pointLabel"),"Hidden detail visible");Is(s.Elements.Count(e=>e.Role==(type=="gantt"?"ganttBar":type=="scatter"?"point":"bubble"))==d.rows.Count,"Data marks lost");}});
        Test("workbook numeric cells use invariant decimals rather than grouping",delegate{ChartDocument d=ChartCore.ImportTable(new List<List<string>>{new List<string>{"categoria","x","y","tamanho"},new List<string>{"A","1.234","-2.345","3.456"}},"bubble",true);Near(Get<double>(d.rows[0],"x"),1.234,0);Near(Get<double>(d.rows[0],"y"),-2.345,0);Near(Get<double>(d.rows[0],"size"),3.456,0);});
        Test("professional JSON rejects invalid relevant data before rendering",delegate{foreach(string type in new[]{"gantt","scatter","bubble"}){string json=ChartCore.Serialize(ChartCore.Example(type));if(type=="gantt"){Reject(delegate{ChartCore.Deserialize(json.Replace("2026-10-05","2026-02-30"));});Reject(delegate{ChartCore.Deserialize(json.Replace("\"progress\":100","\"progress\":101"));});}else{Reject(delegate{ChartCore.Deserialize(json.Replace("\"x\":-20","\"x\":null"));});if(type=="bubble")Reject(delegate{ChartCore.Deserialize(json.Replace("\"size\":20","\"size\":0"));});}}});
        Test("dense professional labels use nearby row numbers without overlapping frames",delegate{ChartDocument d=ChartCore.Example("scatter");d.rows=Enumerable.Range(0,80).Select(i=>new ChartRow{label="Categoria "+i+" desenvolvimento",x=(i%10)*10,y=(i/10)*10}).ToList();Scene scene=ChartCore.BuildScene(d);List<SceneElement> labels=scene.Elements.Where(e=>e.Role=="pointLabel").ToList();Is(labels.Count==80,"Category label lost");Is(labels[0].Text=="1"&&labels[79].Text=="80","Dense labels are not table row numbers");Is(scene.Elements.Any(e=>e.Role=="insight"&&e.Text.Contains("ordem das linhas da tabela")),"Row mapping unexplained");for(int i=0;i<labels.Count;i++){SceneElement point=scene.Elements.First(e=>e.Role=="point"&&e.Category==i);Is(Math.Abs(labels[i].X+labels[i].W/2-point.X-point.W/2)<80&&Math.Abs(labels[i].Y+labels[i].H/2-point.Y-point.H/2)<80,"Row badge too far from point");for(int j=i+1;j<labels.Count;j++)Is(!(labels[i].X<labels[j].X+labels[j].W&&labels[i].X+labels[i].W>labels[j].X&&labels[i].Y<labels[j].Y+labels[j].H&&labels[i].Y+labels[i].H>labels[j].Y),"Labels overlap");}});
        Console.WriteLine(passed+" passed; "+failed+" failed");return failed==0?0:1;
    }
}
